select lives_ok($$select customer_api.save_calendar_plan_v1('11700000-0000-4000-8000-000000000005','11700000-0000-4000-8000-000000000011',0,'11700000-0000-4000-8000-000000000010','11700000-0000-4000-8000-000000000008','Lift monthly','2026-01-31','months',1,true,'["Check doors","Test alarm"]')$$,'Calendar plan created');
