select lives_ok($$select customer_api.generate_calendar_order_v1('11700000-0000-4000-8000-000000000005','11700000-0000-4000-8000-000000000011','2026-01-31')$$,'Retry is idempotent');
select is((select count(*)::integer from maintenance.plan_occurrences where plan_id='11700000-0000-4000-8000-000000000011'),1,'No duplicate occurrence');
select lives_ok($$select customer_api.save_calendar_plan_v1('11700000-0000-4000-8000-000000000005','11700000-0000-4000-8000-000000000011',3,'11700000-0000-4000-8000-000000000010','11700000-0000-4000-8000-000000000008','Lift monthly','2026-01-31','months',1,false,'["Check doors","Test alarm"]')$$,'Plan disabled');
select throws_ok($$select customer_api.generate_calendar_order_v1('11700000-0000-4000-8000-000000000005','11700000-0000-4000-8000-000000000011','2026-02-28')$$,'22023','plan_disabled','Disabled plan cannot generate');
